<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use DI\ContainerBuilder;
use Slim\Psr7\Factory\ServerRequestFactory;
use Slim\Psr7\Response;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms\LoginForm;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\PublicLogin;
use Civi\Lughauth\Features\Oidc\DelegateLogin\Application\DelegateLogin;
use Civi\Lughauth\Features\Oidc\User\Domain\PublicLoginAuthResponse;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Unit tests for {@see LoginForm} step integration.
 */
final class LoginFormStepUnitTest extends TestCase
{
    private array $serverBackup = [];

    protected function setUp(): void
    {
        $this->serverBackup = $_SERVER;
        $_SERVER['HTTPS'] = 'on';
        $_SERVER['HTTP_HOST'] = 'example.com';
        $_SERVER['SCRIPT_NAME'] = '/index.php';
    }

    protected function tearDown(): void
    {
        $_SERVER = $this->serverBackup;
    }

    /**
     * Verifies run() uses StepInput to authenticate when CSID is provided.
     */
    public function testRunProceedsWithStepInput(): void
    {
        /* Arrange: build flow context and StepInput. */
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/tenant1/authorize')
            ->withQueryParams([
                'response_type' => 'code',
                'client_id' => 'client-123',
                'state' => 'state-xyz',
                'redirect_uri' => 'https://client.example/callback',
                'scope' => 'openid profile',
                'nonce' => 'nonce-abc',
            ]);

        $builder = new ContainerBuilder();
        $config = $this->createMock(AppConfig::class);
        $context = new Context($builder, $config);
        $flow = OidcFlowContext::fromRequest($request, 'tenant1', $context);

        $client = new ClientData('client-123', ['code'], true);
        $authRequest = new AuthenticationRequest(
            client: $client,
            scope: 'openid profile',
            redirect: 'https://client.example/callback',
            responseType: 'code',
            audiences: ['client-123']
        );

        $input = new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: new ChallengesState(),
            body: [
                'username' => 'user@example.com',
                'password' => 'enc-pass'
            ],
            request: $request
        );

        $authResponse = $this->createMock(PublicLoginAuthResponse::class);

        $securer = $this->createMock(HtmlSecurer::class);
        $securer->expects($this->once())
            ->method('decrypt')
            ->with('enc-pass')
            ->willReturn('plain-pass');

        $publicLogin = $this->createMock(PublicLogin::class);
        $publicLogin->expects($this->once())
            ->method('autenticateWithState')
            ->with(
                $authRequest,
                $this->isInstanceOf(ChallengesState::class),
                'tenant1',
                'user@example.com',
                'plain-pass',
                'https://example.com/openid/tenant1',
                'csid-123',
                'state-xyz',
                'nonce-abc'
            )
            ->willReturn($authResponse);

        $form = new LoginForm(
            $this->createMock(MessageProvider::class),
            $publicLogin,
            $this->createMock(DecorateHtml::class),
            $securer,
            $this->createMock(DelegateLogin::class)
        );

        /* Act: run the step with CSID. */
        $result = $form->run($input, new Response(), null, null, 'csid-123');

        /* Assert: proceed result is returned. */
        $this->assertSame(StepResult::TYPE_PROCEED, $result->type);
        $this->assertSame($authResponse, $result->authResponse);
    }
}
